#region Using

using System;
using System.Data;
using System.Collections;
using DCore;

#endregion

namespace SMSObject
{
	public partial class SMS_Item_Partner
	{
		#region Member Variables

		private long? lngItemPartnerID = null;
		private long? lngItemID = null;//Mã hàng hoá
		private long? lngPartnerID = null;//Mã kho hàng
		private decimal? decUnitWeight = null;//Tỉ trọng theo từng Đối tác
		private decimal? decPrice = null;//Đơn giá nhập/xuất mặc định theo từng Đối tác
		private DateTime? dtmCreatedDate = null;//Ngày tạo
		private string strCreatedUser = null;//Người tạo
		private IData objIData = null;
		private bool bolIsExistIData = false;
		private Exception objErrorException = null;

		#endregion

		#region Properties

		public long? ItemPartnerID
		{
			get { return lngItemPartnerID; }
			set { lngItemPartnerID = value; }
		}
		public long? ItemID
		{
			get { return lngItemID; }
			set { lngItemID = value; }
		}
		public long? PartnerID
		{
			get { return lngPartnerID; }
			set { lngPartnerID = value; }
		}
		public decimal? UnitWeight
		{
			get { return decUnitWeight; }
			set { decUnitWeight = value; }
		}
		public decimal? Price
		{
			get { return decPrice; }
			set { decPrice = value; }
		}
		public DateTime? CreatedDate
		{
			get { return dtmCreatedDate; }
			set { dtmCreatedDate = value; }
		}
		public string CreatedUser
		{
			get { return strCreatedUser; }
			set { strCreatedUser = value; }
		}
		public IData IDB
		{
			get { return objIData; }
			set
			{
				objIData = value;
				bolIsExistIData = (value != null);
			}
		}
		public Exception ErrorException
		{
			get { return objErrorException; }
			set { objErrorException = value; }
		}

		#endregion

		#region Methods

		public bool Parse(IDataReader reader)
		{
			try
			{
				for (int i = 0; i < reader.FieldCount; i++)
				{
					if (reader.GetName(i).ToUpper().Equals(C_ItemPartnerID.ToUpper()) && !Convert.IsDBNull(reader[C_ItemPartnerID])) this.lngItemPartnerID = Convert.ToInt64(reader[C_ItemPartnerID]);
					if (reader.GetName(i).ToUpper().Equals(C_ItemID.ToUpper()) && !Convert.IsDBNull(reader[C_ItemID])) this.lngItemID = Convert.ToInt64(reader[C_ItemID]);
					if (reader.GetName(i).ToUpper().Equals(C_PartnerID.ToUpper()) && !Convert.IsDBNull(reader[C_PartnerID])) this.lngPartnerID = Convert.ToInt64(reader[C_PartnerID]);
					if (reader.GetName(i).ToUpper().Equals(C_UnitWeight.ToUpper()) && !Convert.IsDBNull(reader[C_UnitWeight])) this.decUnitWeight = Convert.ToDecimal(reader[C_UnitWeight]);
					if (reader.GetName(i).ToUpper().Equals(C_Price.ToUpper()) && !Convert.IsDBNull(reader[C_Price])) this.decPrice = Convert.ToDecimal(reader[C_Price]);
					if (reader.GetName(i).ToUpper().Equals(C_CreatedDate.ToUpper()) && !Convert.IsDBNull(reader[C_CreatedDate])) this.dtmCreatedDate = Convert.ToDateTime(reader[C_CreatedDate]);
					if (reader.GetName(i).ToUpper().Equals(C_CreatedUser.ToUpper()) && !Convert.IsDBNull(reader[C_CreatedUser])) this.strCreatedUser = Convert.ToString(reader[C_CreatedUser]);
				}
				return true;
			}
			catch (Exception objEx)
			{
				new SystemError(SystemConfig.ConnectionString, "Lỗi khi Parse(IDataReader) trong SMS_Item_Partner", objEx);
				this.objErrorException = objEx;
				return false;
			}
		}

		public bool Parse(DataRow drw)
		{
			try
			{
				if (drw.Table.Columns.Contains(C_ItemPartnerID) && !Convert.IsDBNull(drw[C_ItemPartnerID])) this.lngItemPartnerID = Convert.ToInt64(drw[C_ItemPartnerID]);
				if (this.lngItemPartnerID == null && drw.Table.Columns.Contains("ItemPartnerIDTemp") && !Convert.IsDBNull(drw["ItemPartnerIDTemp"])) this.lngItemPartnerID = Convert.ToInt64(drw["ItemPartnerIDTemp"]);
				if (!Convert.IsDBNull(drw[C_ItemID])) this.lngItemID = Convert.ToInt64(drw[C_ItemID]);
				if (!Convert.IsDBNull(drw[C_PartnerID])) this.lngPartnerID = Convert.ToInt64(drw[C_PartnerID]);
				if (drw.Table.Columns.Contains(C_UnitWeight) && !Convert.IsDBNull(drw[C_UnitWeight])) this.decUnitWeight = Convert.ToDecimal(drw[C_UnitWeight]);
				if (drw.Table.Columns.Contains(C_Price) && !Convert.IsDBNull(drw[C_Price])) this.decPrice = Convert.ToDecimal(drw[C_Price]);
				if (drw.Table.Columns.Contains(C_CreatedDate) && !Convert.IsDBNull(drw[C_CreatedDate])) this.dtmCreatedDate = Convert.ToDateTime(drw[C_CreatedDate]);
				if (drw.Table.Columns.Contains(C_CreatedUser) && !Convert.IsDBNull(drw[C_CreatedUser])) this.strCreatedUser = Convert.ToString(drw[C_CreatedUser]);
				return true;
			}
			catch (Exception objEx)
			{
				new SystemError(SystemConfig.ConnectionString, "Lỗi khi Parse(DataRow) trong SMS_Item_Partner", objEx);
				this.objErrorException = objEx;
				return false;
			}
		}

		public bool Get()
		{
			if (!bolIsExistIData)
				objIData = DCore.Data.CreateData();
			try
			{
				objIData.CreateNewStoredProcedure("SMS_Item_Partner_GET");
				objIData.AddParameter(P_ItemPartnerID, this.lngItemPartnerID);
				IDataReader reader = objIData.ExecStoreToDataReader();
				if (reader.Read())
				{
					if (Parse(reader))
					{
						reader.Close();
						return true;
					}
				}
				reader.Close();
				return false;
			}
			catch (Exception objEx)
			{
				if (bolIsExistIData)
					this.RollBackTransaction();
				new SystemError(SystemConfig.ConnectionString, "Lỗi nạp thông tin SMS_Item_Partner", objEx);
				this.objErrorException = objEx;
				return false;
			}
			finally
			{
				if (!bolIsExistIData)
					objIData.Disconnect();
			}
		}

		public SMS_Item_Partner Get(long? lngItemPartnerID)
		{
			SMS_Item_Partner obj = new SMS_Item_Partner();
			if (objIData != null)
				obj.IDB = objIData;
			obj.ItemPartnerID = lngItemPartnerID;
			if (obj.Get())
				return obj;
			this.objErrorException = obj.ErrorException;
			return null;
		}

		public DataTable GetDataTable(string storeName, params object[] pars)
		{
			if (!bolIsExistIData)
				objIData = DCore.Data.CreateData();
			try
			{
				objIData.CreateNewStoredProcedure(storeName);
				objIData.AddParameter(pars);
				return objIData.ExecStoreToDataTable();
			}
			catch (Exception objEx)
			{
				if (bolIsExistIData)
					this.RollBackTransaction();
				new SystemError(SystemConfig.ConnectionString, "Lỗi thực hiện store " + storeName + " trong SMS_Item_Partner", objEx);
				this.objErrorException = objEx;
				return null;
			}
			finally
			{
				if (!bolIsExistIData)
					objIData.Disconnect();
			}
		}

		public bool Add()
		{
			if (!bolIsExistIData)
				objIData = DCore.Data.CreateData();
			try
			{
				objIData.CreateNewStoredProcedure("SMS_Item_Partner_ADD");
				objIData.AddParameter(P_ItemID, this.lngItemID);
				objIData.AddParameter(P_PartnerID, this.lngPartnerID);
				objIData.AddParameter(P_UnitWeight, this.decUnitWeight);
				objIData.AddParameter(P_Price, this.decPrice);
				objIData.AddParameter(P_CreatedUser, this.strCreatedUser);
				this.lngItemPartnerID = Convert.ToInt64(objIData.ExecStoreToString());
				return true;
			}
			catch (Exception objEx)
			{
				if (bolIsExistIData)
					this.RollBackTransaction();
				new SystemError(SystemConfig.ConnectionString, "Lỗi thêm thông tin SMS_Item_Partner", objEx);
				this.objErrorException = objEx;
				return false;
			}
			finally
			{
				if (!bolIsExistIData)
					objIData.Disconnect();
			}
		}

		public bool Update()
		{
			if (!bolIsExistIData)
				objIData = DCore.Data.CreateData();
			try
			{
				objIData.CreateNewStoredProcedure("SMS_Item_Partner_EDIT");
				objIData.AddParameter(P_ItemPartnerID, this.lngItemPartnerID);
				objIData.AddParameter(P_ItemID, this.lngItemID);
				objIData.AddParameter(P_PartnerID, this.lngPartnerID);
				objIData.AddParameter(P_UnitWeight, this.decUnitWeight);
				objIData.AddParameter(P_Price, this.decPrice);
				objIData.ExecNonQuery();
				return true;
			}
			catch (Exception objEx)
			{
				if (bolIsExistIData)
					this.RollBackTransaction();
				new SystemError(SystemConfig.ConnectionString, "Lỗi cập nhật thông tin SMS_Item_Partner", objEx);
				this.objErrorException = objEx;
				return false;
			}
			finally
			{
				if (!bolIsExistIData)
					objIData.Disconnect();
			}
		}

		public bool Delete()
		{
			if (!bolIsExistIData)
				objIData = DCore.Data.CreateData();
			try
			{
				objIData.CreateNewStoredProcedure("SMS_Item_Partner_DELETE");
				objIData.AddParameter(P_ItemPartnerID, this.lngItemPartnerID);
				objIData.ExecNonQuery();
				return true;
			}
			catch (Exception objEx)
			{
				if (bolIsExistIData)
					this.RollBackTransaction();
				new SystemError(SystemConfig.ConnectionString, "Lỗi xóa thông tin SMS_Item_Partner", objEx);
				this.objErrorException = objEx;
				return false;
			}
			finally
			{
				if (!bolIsExistIData)
					objIData.Disconnect();
			}
		}

		public bool Delete(long? lngItemPartnerID)
		{
			this.lngItemPartnerID = lngItemPartnerID;
			return this.Delete();
		}

		public bool BeginTransaction()
		{
			objIData = DCore.Data.CreateData();
			try
			{
				objIData.Connect();
				objIData.BeginTransaction();
				bolIsExistIData = true;
				return true;
			}
			catch (Exception objEx)
			{
				this.objErrorException = objEx;
				return false;
			}
		}

		public void CommitTransaction()
		{
			objIData.CommitTransaction();
			objIData.Disconnect();
			bolIsExistIData = false;
		}

		public void RollBackTransaction()
		{
			objIData.RollBackTransaction();
			objIData.Disconnect();
			bolIsExistIData = false;
		}

		#endregion

		#region Constructor

		public SMS_Item_Partner()
		{
		}
		public SMS_Item_Partner(long? lngItemPartnerID)
		{
			this.lngItemPartnerID = lngItemPartnerID;
			this.Get();
		}

		#endregion

		#region Variable Static

		public const String P_ItemPartnerID = "@" + C_ItemPartnerID;
		public const String P_ItemID = "@" + C_ItemID;
		public const String P_PartnerID = "@" + C_PartnerID;
		public const String P_UnitWeight = "@" + C_UnitWeight;
		public const String P_Price = "@" + C_Price;
		public const String P_CreatedDate = "@" + C_CreatedDate;
		public const String P_CreatedUser = "@" + C_CreatedUser;

		public const String C_ItemPartnerID = "ItemPartnerID";
		public const String C_ItemID = "ItemID";
		public const String C_PartnerID = "PartnerID";
		public const String C_UnitWeight = "UnitWeight";
		public const String C_Price = "Price";
		public const String C_CreatedDate = "CreatedDate";
		public const String C_CreatedUser = "CreatedUser";

		#endregion
	}
}

