#region Partner Methods

public void LoadPartner()
{
    SMS_Item_Partner obj = new SMS_Item_Partner();
    dtbPartner = obj.GetDataTable("SMS_Item_Partner_SearchForEdit", "@ItemID", lngInputItemID == null ? -1 : lngInputItemID);

    if (dtbPartner != null)
    {
        gcPartner.DataSource = dtbPartner;
        gvPartner.RowFilter = "IsDeleted <> 1";
        SystemService.SYS_GridColumnService.InitGridColumn(gvPartner, "SMS_Item_Partner_SearchForEdit", bolIsRefresh);
        gvPartner.BestFitColumns();
    }
}

public void SelectPartner()
{
    if (dtbPartner == null)
    {
        ErrorManager.Error("Chưa tải dữ liệu khách hàng, thử nhấn F5 để tải lại!");
        return;
    }

    string strListID = "";
    StockManager.Declaration.Partner.frmPartnerSelect frm = StockManager.Declaration.Partner.frmPartnerSelect.Instance;
    frm.ISMultiSelect = true;
    frm.ShowDialog();
    if (frm.IsOk)
    {
        strListID = frm.ListIDSelected;
    }
    else
        return;

    if (strListID != "" && strListID != null)
    {
        DataTable dtbList = frm.Data;
        string[] arrID = strListID.Split(',');
        foreach (string id in arrID)
        {
            if (id != "")
            {
                DataRow[] rows = dtbPartner.Select("PartnerID = '" + id + "'");
                if (rows.Length == 0)
                {
                    DataRow[] rowsPartner = dtbList.Select("PartnerID = " + id);
                    if (rowsPartner.Length > 0)
                    {
                        DataRow drwNew = dtbPartner.NewRow();
                        drwNew["PartnerID"] = rowsPartner[0]["PartnerID"];
                        drwNew["PartnerCode"] = rowsPartner[0]["PartnerCode"];
                        drwNew["PartnerName"] = rowsPartner[0]["PartnerName"];
                        drwNew["UnitWeight"] = txtUnitWeight.EditValueDecimal;
                        drwNew["Price"] = txtInputPrice.EditValueDecimal;
                        drwNew["IsDeleted"] = 0;
                        dtbPartner.Rows.Add(drwNew);
                        ProcessRow_Partner(drwNew);
                    }
                }
                else
                {
                    rows[0]["IsDeleted"] = 0;
                }
            }
        }
    }
}

public bool DeletePartner()
{
    int[] arrRowIndex = gvPartner.GetSelectedRows();
    if (arrRowIndex.Length > 0)
    {
        for (int i = arrRowIndex.Length - 1; i >= 0; i--)
        {
            DataRow drw = gvPartner.GetDataRow(arrRowIndex[i]);
            if (drw != null)
            {
                drw["IsDeleted"] = 1;
            }
        }
        return true;
    }
    return false;
}

public bool SavePartner(DCore.IData objIDB)
{
    if (dtbPartner != null)
    {
        foreach (DataRow drw in dtbPartner.Rows)
        {
            if (drw.RowState == DataRowState.Added || drw.RowState == DataRowState.Modified)
            {
                SMS_Item_Partner item = new SMS_Item_Partner();
                item.IDB = objIDB;

                if (item.Parse(drw))
                {
                    item.ItemID = itemItemEditing.ItemID;
                    if (item.ItemPartnerID == null)
                    {
                        if (drw["IsDeleted"].ToString() == "0")
                        {
                            item.CreatedUser = UserSession.Username;
                            if (!item.Add())
                            {
                                ErrorManager.Error("Việc thêm thông tin khách hàng bị lỗi!");
                                return false;
                            }
                            drw["ItemPartnerIDTemp"] = item.ItemPartnerID;
                        }
                    }
                    else
                    {
                        if (drw["IsDeleted"].ToString() == "1")
                        {
                            if (!item.Delete())
                            {
                                ErrorManager.Error("Việc xoá thông tin khách hàng bị lỗi!");
                                return false;
                            }
                        }
                        else
                        {
                            if (!item.Update())
                            {
                                ErrorManager.Error("Việc cập nhật thông tin khách hàng bị lỗi!");
                                return false;
                            }
                        }
                    }
                }
                else
                {
                    ErrorManager.Error("Việc lấy thông tin khách hàng cập nhật bị lỗi!");
                    item.RollBackTransaction();
                    return false;
                }
            }
        }
    }
    return true;
}

private bool ProcessRow_Partner(DataRow drw)
{
    if (drw["UnitWeight"].ToString() == "")
        drw["UnitWeight"] = 0;

    if (drw["Price"].ToString() == "")
        drw["Price"] = 0;

    if (drw["IsDeleted"].ToString() == "")
        drw["IsDeleted"] = 0;

    return true;
}

