private long GetNewItemPartnerID(DCore.IData objIDB)
{
    long lngNewID = 1;
    SMS_Item_Partner obj = new SMS_Item_Partner();
    obj.IDB = objIDB;
    DataTable dtbAll = obj.GetAll();
    if (dtbAll != null)
    {
        foreach (DataRow drwMax in dtbAll.Rows)
        {
            if (!Convert.IsDBNull(drwMax[SMS_Item_Partner.C_ItemPartnerID]))
            {
                long lngId = Convert.ToInt64(drwMax[SMS_Item_Partner.C_ItemPartnerID]);
                if (lngId >= lngNewID)
                    lngNewID = lngId + 1;
            }
        }
    }
    return lngNewID;
}

